/**
 * A committed schema document, byte for byte, for a graph exercising every
 * slice the serializer writes or conditionally omits.
 *
 * A stored version is compared against the graph by hash, so a serializer
 * change that adds, renames or reorders a field changes the hash of every
 * document already stored. The fixture is written once and never
 * regenerated by the test that reads it: the serializer must reproduce it,
 * and a store whose row holds it must reopen `unchanged` without rewriting
 * it. A deliberate change to the serialized form updates the fixture in the
 * same commit, with its upgrade path stated.
 */
import { readFileSync } from "node:fs";
import path from "node:path";

import type Database from "better-sqlite3";
import { afterEach, describe, expect, it, vi } from "vitest";
import { z } from "zod";

import {
  defineEdge,
  defineGraph,
  defineGraphExtension,
  defineNode,
  defineNodeIndex,
  disjointWith,
  hasPart,
  partOf,
  subClassOf,
  type UniqueConstraint,
} from "../src";
import { createLocalSqliteBackend } from "../src/backend/sqlite/local";
import { mergeGraphExtension } from "../src/graph-extension/merge";
import { applyDeprecatedKinds } from "../src/schema/manager";
import { computeSchemaHash, serializeSchema } from "../src/schema/serializer";
import { type SerializedSchema } from "../src/schema/types";
import { createAdapterStoreWithSchema } from "../src/store/store";
import { requireDefined } from "../src/utils/presence";

const FIXTURE_PATH = path.join(
  import.meta.dirname,
  "fixtures",
  "golden-schema-document.json",
);

/** The fixture's `generatedAt`, the one field read off the clock. */
const GOLDEN_GENERATED_AT = "2026-11-03T00:00:00.000Z";

/** `computeSchemaHash` of the fixture, as committed with it. */
const GOLDEN_SCHEMA_HASH = "9aa79a42455e4821";

const Library = defineNode("GoldenLibrary", {
  schema: z.object({ name: z.string(), code: z.string() }),
  annotations: { owner: "catalog" },
});
const Shelf = defineNode("GoldenShelf", {
  schema: z.object({ label: z.string().min(1) }),
});
const Book = defineNode("GoldenBook", {
  schema: z.object({ title: z.string(), isbn: z.string().optional() }),
});
const RareBook = defineNode("GoldenRareBook", {
  schema: z.object({
    title: z.string(),
    isbn: z.string().optional(),
    vault: z.string(),
  }),
});
const Patron = defineNode("GoldenPatron", {
  schema: z.object({ email: z.string() }),
});
const Legacy = defineNode("GoldenLegacy", { schema: z.object({}) });
const Section = defineNode("GoldenSection", { schema: z.object({}) });

const shelfIn = defineEdge("goldenShelfIn", { schema: z.object({}) });
const holds = defineEdge("goldenHolds", { schema: z.object({}) });
const cites = defineEdge("goldenCites", { schema: z.object({}) });
const nests = defineEdge("goldenNests", { schema: z.object({}) });
const borrows = defineEdge("goldenBorrows", {
  schema: z.object({ loanCode: z.string() }),
});

/**
 * The types require `scope` and `collation`; a JavaScript caller can omit
 * them, and `defineGraph` writes the defaults in.
 */
function defaultedUnique(name: string, field: string): UniqueConstraint {
  return { name, fields: [field] } as unknown as UniqueConstraint;
}

const baseGraph = defineGraph({
  id: "schema_golden_document",
  annotations: { domain: "library", revision: 1 },
  identity: { sameIdAcrossKinds: "ignore" },
  nodes: {
    GoldenLibrary: {
      type: Library,
      unique: [
        defaultedUnique("golden_library_name", "name"),
        {
          name: "golden_library_code",
          fields: ["code"],
          scope: "kind",
          collation: "caseInsensitive",
        },
      ],
    },
    GoldenShelf: { type: Shelf },
    GoldenBook: {
      type: Book,
      unique: [
        {
          name: "golden_book_isbn",
          fields: ["isbn"],
          scope: "kindWithSubClasses",
          collation: "binary",
          where: (fields) => requireDefined(fields["isbn"]).isNotNull(),
        },
      ],
    },
    GoldenRareBook: { type: RareBook },
    GoldenPatron: { type: Patron },
    GoldenLegacy: { type: Legacy },
    GoldenSection: { type: Section },
  },
  edges: {
    goldenShelfIn: {
      type: shelfIn,
      from: [Shelf],
      to: [Library],
      cardinality: "one",
    },
    goldenHolds: {
      type: holds,
      from: [Shelf],
      to: [Book],
      targetCardinality: "oneActive",
    },
    goldenCites: {
      type: cites,
      from: [Book],
      to: [Book],
      acyclic: true,
      endpointExistence: "currentlyValid",
    },
    goldenNests: {
      type: nests,
      from: [Section],
      to: [Section],
      cardinality: "one",
    },
    goldenBorrows: {
      type: borrows,
      from: [Patron],
      to: [Book],
      matchIdentity: { name: "golden-loan", fields: ["loanCode"] },
    },
  },
  ontology: [
    subClassOf(RareBook, Book),
    disjointWith(Patron, Book),
    partOf(Shelf, Library, {
      via: shelfIn,
      existence: "required",
      partSide: "from",
    }),
    hasPart(Shelf, Book, { via: holds }),
    // The edge admits the pair both ways, so the side is what decides it
    // and the document keeps it.
    partOf(Section, Section, { via: nests, partSide: "from" }),
  ],
  indexes: [
    defineNodeIndex(Book, { fields: ["title"] }),
    defineNodeIndex(Patron, {
      fields: ["email"],
      where: (props) => props.email.isNotNull(),
    }),
  ],
});

const goldenGraph = applyDeprecatedKinds(
  mergeGraphExtension(
    baseGraph,
    defineGraphExtension({
      nodes: {
        GoldenArchive: {
          properties: { box: { type: "string" } },
          unique: [{ name: "golden_archive_box", fields: ["box"] }],
        },
      },
    }),
  ),
  ["GoldenLegacy"],
);

function serializedBytes(): string {
  vi.useFakeTimers({ toFake: ["Date"] });
  try {
    vi.setSystemTime(new Date(GOLDEN_GENERATED_AT));
    return JSON.stringify(serializeSchema(goldenGraph, 1));
  } finally {
    vi.useRealTimers();
  }
}

/** The fixture's bytes: the compact JSON a schema row stores. */
function fixtureBytes(): string {
  return JSON.stringify(JSON.parse(readFileSync(FIXTURE_PATH, "utf8")));
}

const backends: ReturnType<typeof createLocalSqliteBackend>["backend"][] = [];
afterEach(async () => {
  for (const backend of backends.splice(0)) await backend.close();
});

describe("the golden schema document", () => {
  it("is what today's serializer writes for the graph, with the committed hash", async () => {
    expect(serializedBytes()).toBe(fixtureBytes());
    expect(
      await computeSchemaHash(JSON.parse(fixtureBytes()) as SerializedSchema),
    ).toBe(GOLDEN_SCHEMA_HASH);
  });

  it("reopens unchanged from a stored row holding it, and leaves the row as written", async () => {
    const { backend, db } = createLocalSqliteBackend();
    backends.push(backend);
    await createAdapterStoreWithSchema(goldenGraph, backend);
    const client = (db as unknown as Readonly<{ $client: Database.Database }>)
      .$client;
    const golden = fixtureBytes();
    client
      .prepare(
        "UPDATE typegraph_schema_versions SET schema_doc = ?, schema_hash = ? WHERE graph_id = ? AND version = 1",
      )
      .run(golden, GOLDEN_SCHEMA_HASH, goldenGraph.id);

    const [, result] = await createAdapterStoreWithSchema(goldenGraph, backend);
    const row = requireDefined(await backend.getActiveSchema(goldenGraph.id));

    expect(result.status).toBe("unchanged");
    expect(row.version).toBe(1);
    expect(row.schema_doc).toBe(golden);
    expect(row.schema_hash).toBe(GOLDEN_SCHEMA_HASH);
  });
});
